\mathsf {inv}{}^{\mathsf  D} \colon  \{X \colon  \mathsf {Obj}\} \{X{}^{\mathsf  D} \colon  \mathsf {Obj}{}^{\mathsf  D}\;X\} \{Y \colon  \mathsf {Obj}\} \{Y{}^{\mathsf  D} \colon  \mathsf {Obj}{}^{\mathsf  D}\;Y\} \{f \colon  \mathsf {Hom}\;X\;Y\} \lparen {}f{}^{\mathsf  D} \colon  \mathsf {Hom}{}^{\mathsf  D}\;X{}^{\mathsf  D}\;Y{}^{\mathsf  D}\;f\rparen {}  \to  \mathsf {Hom}{}^{\mathsf  D}\;Y{}^{\mathsf  D}\;X{}^{\mathsf  D}\;\lparen {}\mathsf {inv}\;f\rparen {}

